<template>
<section><div class="page-head"><div><span class="eyebrow">Extend your media center</span><h1 class="page-title">Add-ons</h1><p class="muted">Install add-ons to connect services and discover more content.</p></div><button class="button-secondary" @click="$emit('navigate','repository')">Browse repository</button></div><div class="grid"><article v-for="addon in state.addons" :key="addon.id" class="tile"><div class="tile-icon">{{addon.icon}}</div><strong>{{addon.name}}</strong><small>{{addon.description}}</small><div class="row" style="margin-top:17px"><button v-if="!state.installed.includes(addon.id)" class="button" @click="$emit('action',{action:'install',payload:addon.id})">Install</button><button v-else class="button-secondary" @click="$emit('action',{action:'open-addon',payload:addon.id})">Open</button><button v-if="state.installed.includes(addon.id)" class="quiet" @click="$emit('action',{action:'addon-settings',payload:addon.id})">Settings</button></div></article></div></section>
</template>
